import "dart:convert";
import "dart:io";

import "package:flutter/material.dart";
import "package:flutter_test/flutter_test.dart";
import "package:melody/ui/shared/theme.dart";
import "package:melody/ui/shared/widgets.dart";

/// The Android launcher icons are generated by tools/build/icons.py from
/// icon_accents.json; these keep that table and the manifest's per-accent
/// launcher entries in step with the theme.
void main() {
  String hex(Color color) =>
      "#${(color.toARGB32() & 0xFFFFFF).toRadixString(16).padLeft(6, "0")}"
          .toUpperCase();

  test("icon_accents.json holds BrandMark's light colors for every accent", () {
    final table =
        jsonDecode(File("../tools/build/icon_accents.json").readAsStringSync())
            as Map<String, dynamic>;
    final expected = {
      for (final accent in themePalettes.keys)
        accent: [
          for (final color in brandMarkColors(
            buildTheme(accent, Brightness.light).colorScheme,
          ))
            hex(color),
        ],
    };
    expect(table, expected, reason: "run tools/build/icons.py after updating");
    for (final accent in themePalettes.keys) {
      expect(
        buildTheme(accent, Brightness.light).colorScheme.onPrimary,
        Colors.white,
        reason: "the generated foreground glyph is white",
      );
    }
  });

  test("the Android manifest has a launcher entry for every accent", () {
    final manifest = File(
      "android/app/src/main/AndroidManifest.xml",
    ).readAsStringSync();
    final aliases = RegExp(
      r'android:name="\.icon\.(\w+)"[^>]*android:icon="@mipmap/ic_launcher_(\w+)"[^>]*android:enabled="(\w+)"',
    ).allMatches(manifest);
    final entries = {for (final m in aliases) m[1]: m[2]};
    for (final accent in themePalettes.keys) {
      expect(entries[accent], accent, reason: "accent $accent has no entry");
    }
    // Android keeps a disabled alias's state across updates but drops an
    // alias the update removes: removing or renaming the enabled one leaves
    // Melody with no launcher entry. Only ever add to this list; a retired
    // accent keeps its entry (LauncherIcon disables it).
    const shipped = [
      "violet",
      "ocean",
      "rose",
      "emerald",
      "amber",
      "slate",
      "blue",
      "teal",
      "coral",
      "magenta",
      "lime",
    ];
    expect(
      entries.keys,
      containsAll(shipped),
      reason: "a shipped launcher entry was removed or renamed",
    );
    expect(
      [...entries.keys.where((a) => !shipped.contains(a))],
      isEmpty,
      reason: "add new launcher entries to the shipped list",
    );
    expect(
      [
        for (final m in aliases)
          if (m[3] == "true") m[1],
      ],
      ["violet"],
      reason: "only the default accent's entry starts enabled",
    );
  });

  test("every accent has a splash theme with its launcher icon", () {
    final themes = File(
      "android/app/src/main/res/values-v31/splash_themes.xml",
    ).readAsStringSync();
    final styles = RegExp(
      r'<style name="LaunchTheme\.(\w+)">\s*<item name="android:windowSplashScreenAnimatedIcon">@mipmap/ic_launcher_(\w+)</item>',
    ).allMatches(themes);
    expect(
      {for (final m in styles) m[1]: m[2]},
      {for (final accent in themePalettes.keys) accent: accent},
      reason: "run tools/build/icons.py after updating",
    );
    expect(
      File(
        "android/app/src/main/kotlin/com/flet/musicplayer/LauncherIcon.kt",
      ).readAsStringSync(),
      contains('getIdentifier("LaunchTheme.\$accent", "style"'),
      reason:
          "getIdentifier takes the resource name with its dots, "
          "not the R field name",
    );
  });
}
